#if UNITY_EDITOR
// Aurelle realism pass, cars: procedural textures for the hero CarConcept.
//
// Every texture here is generated by code (fixed seeds, no third-party pixels) and written to
// Assets/Materials/Realism/Cars/Textures/Concept as PNG (Git LFS) only when its bytes change, so a second run
// rewrites nothing and the GUIDs stay. Images are authored in glTF UV orientation (row 0 = v 0, the top of the
// image); the PNG rows are flipped on write, so the glTFast graphs' own V flip (_ST y = -1) samples them upright.
//   Flakes_Normal / Flakes_MR      tileable metallic-paint flakes (0.5 mm on a 3 cm tile): slightly tilted facet
//                                  normals and a glTF metallic-roughness mask (G roughness, B metallic) - the flakes
//                                  smoother and more metallic than the pigment between them, so they glint in the
//                                  highlights while diffuse areas stay even; mip-mapping smooths them out at distance
//                                  (the paints use only the MR mask; Flakes_Normal is generated but not assigned, see
//                                  CarsRealism's paint specs)
//   Tyre_Sidewall_R / _L_Normal,   sidewall in the tyre's planar disc UVs: bead and rim-protector ridges and raised
//   Tyre_Sidewall_R / _L_MR        lettering "AURELLE SPORT", "255/35 R20 97Y", "TUBELESS RADIAL" that is a little
//                                  smoother than the flank (the left tyres' UVs are mirrored, so they get mirrored maps)
//   BrakeDisc_Base / _Normal / _MR polar disc UVs (u angle, v radius): machined hat, brushed friction ring with
//                                  concentric turning marks, three spiral rows of chamfered cross-drilled holes
//   Leather_Normal, LeatherPerf_Base  pebbled leather grain; the hole grid of the perforated inserts (base mask)
//   Alcantara_Normal               fine suede nap
//   Carbon_Base / _Normal          2x2 twill weave of 3K tows with fibre striations
//   Brushed_Normal                 straight brushing lines for the aluminium trims
//   Display_Emissive               instrument display: speed, rev bar, gear, range, AURELLE
//   License_Plate                  the rear plate (in place of the GLB's KHRONOS logo atlas): AURELLE, MOTOR HOUSE
//   Caliper_Base                   the calipers' paint with the AURELLE logo (caliper UVs, see CarsRealismMeshes.cs)
//   Windscreen_Frit                the windscreen tint with its black ceramic frit border (windscreen UVs, ditto)
// Textures this tool no longer generates are deleted from the folder.
using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using UnityEditor;
using UnityEngine;

public static partial class CarsRealism
{
    public const string ConceptTextureFolder = MaterialFolder + "/Textures/Concept";

    /// <summary>Generates (or reuses) every procedural texture; name -> texture asset.</summary>
    private static Dictionary<string, Texture2D> BuildConceptTextures(StringBuilder report)
    {
        var result = new Dictionary<string, Texture2D>();
        int written = 0, kept = 0;
        void Add(string name, Gen g)
        {
            bool changed;
            result[name] = g.Save(ConceptTextureFolder + "/Car_Concept_" + name + ".png", out changed);
            if (changed) written++; else kept++;
        }

        // Paint flakes: 512 px tile, 64 x 64 cells (one flake each at most).
        FlakeMaps(512, 64, out Gen flakeN, out Gen flakeMr);
        Add("Flakes_Normal", flakeN);
        Add("Flakes_MR", flakeMr);

        // Tyre sidewalls (2048 px disc).
        float[] side = SidewallHeight(2048, out float[] raised);
        Add("Tyre_Sidewall_R_Normal", Gen.NormalFromHeight(side, 2048, 2048, 14f, false, Kind.Normal, 1024, 8));
        Add("Tyre_Sidewall_L_Normal", Gen.NormalFromHeight(MirrorU(side, 2048, 2048), 2048, 2048, 14f, false, Kind.Normal, 1024, 8));
        Add("Tyre_Sidewall_R_MR", SidewallMr(raised, 2048, false));
        Add("Tyre_Sidewall_L_MR", SidewallMr(raised, 2048, true));

        // Brake disc (u: angle, v: radius).
        DiscMaps(2048, 256, out Gen discBase, out Gen discN, out Gen discMr);
        Add("BrakeDisc_Base", discBase);
        Add("BrakeDisc_Normal", discN);
        Add("BrakeDisc_MR", discMr);

        // Interior.
        float[] grain = LeatherGrain(512, 38, 11);
        Add("Leather_Normal", Gen.NormalFromHeight(grain, 512, 512, 2.2f, true, Kind.Normal, 512, 4));
        Add("LeatherPerf_Base", LeatherPerforated(512, grain));
        Add("Alcantara_Normal", Gen.NormalFromHeight(Suede(256, 23), 256, 256, 1.1f, true, Kind.Normal, 256, 4));
        CarbonTwill(512, 8, out Gen carbonBase, out Gen carbonN);
        Add("Carbon_Base", carbonBase);
        Add("Carbon_Normal", carbonN);
        Add("Brushed_Normal", Gen.NormalFromHeight(Brushed(512, 31), 512, 512, 1.4f, true, Kind.Normal, 512, 8));
        Add("Display_Emissive", Display(1024, 256));
        Add("License_Plate", LicensePlate(1024, 256));
        Add("Caliper_Base", CaliperBase(512, new Color(0.66f, 0.022f, 0.028f)));
        Mesh windscreen = ConceptGlbMesh("BodyWindshield");
        if (windscreen != null) Add("Windscreen_Frit", WindscreenFrit(windscreen, 1024, WindscreenTint, WindscreenAlpha));
        else Debug.LogWarning("CarsRealism: BodyWindshield mesh not found in " + ConceptGlb + "; no frit texture");

        int deleted = 0;
        foreach (string guid in AssetDatabase.FindAssets("t:Texture2D", new[] { ConceptTextureFolder }))
        {
            string path = AssetDatabase.GUIDToAssetPath(guid);
            string stem = Path.GetFileNameWithoutExtension(path);
            if (!stem.StartsWith("Car_Concept_", StringComparison.Ordinal) || result.ContainsKey(stem.Substring("Car_Concept_".Length))) continue;
            AssetDatabase.DeleteAsset(path);
            deleted++;
        }
        report.Append(written + " written, " + kept + " unchanged, " + deleted + " stale deleted in " + ConceptTextureFolder);
        return result;
    }

    // ------------------------------------------------------------------------------------------------ texture io

    private enum Kind { Color, Data, Normal }

    /// <summary>One generated image in glTF orientation (row 0 = top) and its import settings.</summary>
    private sealed class Gen
    {
        public int W, H;
        public Color32[] Px; // row 0 = top
        public Kind Kind;
        public int AndroidMax = 1024;
        public int Aniso = 4;
        public bool Alpha;

        public static Gen NormalFromHeight(float[] h, int w, int hgt, float strength, bool wrap, Kind kind, int androidMax, int aniso)
        {
            var g = new Gen { W = w, H = hgt, Px = new Color32[w * hgt], Kind = kind, AndroidMax = androidMax, Aniso = aniso };
            for (int y = 0; y < hgt; y++)
            {
                for (int x = 0; x < w; x++)
                {
                    float l = Sample(h, w, hgt, x - 1, y, wrap), r = Sample(h, w, hgt, x + 1, y, wrap);
                    float u = Sample(h, w, hgt, x, y - 1, wrap), d = Sample(h, w, hgt, x, y + 1, wrap);
                    // +X right, +Y up (towards row 0): n = (-dh/dx, +dh/drow, 1)
                    var n = new Vector3(-(r - l) * 0.5f * strength, (d - u) * 0.5f * strength, 1f).normalized;
                    g.Px[y * w + x] = EncodeNormal(n);
                }
            }
            return g;
        }

        public Texture2D Save(string path, out bool changed)
        {
            EnsureFolderPath(Path.GetDirectoryName(path).Replace('\\', '/'));
            var tex = new Texture2D(W, H, TextureFormat.RGBA32, false, Kind != Kind.Color);
            var flipped = new Color32[Px.Length];
            for (int y = 0; y < H; y++) Array.Copy(Px, y * W, flipped, (H - 1 - y) * W, W);
            tex.SetPixels32(flipped);
            tex.Apply(false);
            byte[] png = tex.EncodeToPNG();
            UnityEngine.Object.DestroyImmediate(tex);
            changed = !File.Exists(path) || !BytesEqual(File.ReadAllBytes(path), png);
            if (changed)
            {
                File.WriteAllBytes(path, png);
                AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceSynchronousImport);
            }
            ConfigureGenerated(path, this);
            return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        }
    }

    private static bool BytesEqual(byte[] a, byte[] b)
    {
        if (a.Length != b.Length) return false;
        for (int i = 0; i < a.Length; i++) if (a[i] != b[i]) return false;
        return true;
    }

    private static void EnsureFolderPath(string folder)
    {
        if (AssetDatabase.IsValidFolder(folder)) return;
        string parent = Path.GetDirectoryName(folder).Replace('\\', '/');
        EnsureFolderPath(parent);
        AssetDatabase.CreateFolder(parent, Path.GetFileName(folder));
    }

    private static void ConfigureGenerated(string path, Gen g)
    {
        var ti = AssetImporter.GetAtPath(path) as TextureImporter;
        if (ti == null) return;
        bool dirty = false;
        var type = g.Kind == Kind.Normal ? TextureImporterType.NormalMap : TextureImporterType.Default;
        if (ti.textureType != type) { ti.textureType = type; dirty = true; }
        bool srgb = g.Kind == Kind.Color;
        if (ti.sRGBTexture != srgb) { ti.sRGBTexture = srgb; dirty = true; }
        var alphaSource = g.Alpha ? TextureImporterAlphaSource.FromInput : TextureImporterAlphaSource.None;
        if (ti.alphaSource != alphaSource) { ti.alphaSource = alphaSource; dirty = true; }
        if (!ti.mipmapEnabled) { ti.mipmapEnabled = true; dirty = true; }
        if (ti.wrapMode != TextureWrapMode.Repeat) { ti.wrapMode = TextureWrapMode.Repeat; dirty = true; }
        if (ti.filterMode != FilterMode.Trilinear) { ti.filterMode = FilterMode.Trilinear; dirty = true; }
        if (ti.anisoLevel != g.Aniso) { ti.anisoLevel = g.Aniso; dirty = true; }
        int max = Mathf.Max(g.W, g.H);
        if (ti.maxTextureSize != max) { ti.maxTextureSize = max; dirty = true; }
        if (ti.textureCompression != TextureImporterCompression.CompressedHQ) { ti.textureCompression = TextureImporterCompression.CompressedHQ; dirty = true; }
        TextureImporterPlatformSettings standalone = ti.GetPlatformTextureSettings("Standalone");
        if (!standalone.overridden || standalone.maxTextureSize != max || standalone.format != TextureImporterFormat.Automatic ||
            standalone.textureCompression != TextureImporterCompression.CompressedHQ)
        {
            standalone.overridden = true;
            standalone.maxTextureSize = max;
            standalone.format = TextureImporterFormat.Automatic;
            standalone.textureCompression = TextureImporterCompression.CompressedHQ;
            ti.SetPlatformTextureSettings(standalone);
            dirty = true;
        }
        TextureImporterPlatformSettings android = ti.GetPlatformTextureSettings("Android");
        int androidMax = Mathf.Min(g.AndroidMax, max);
        if (!android.overridden || android.maxTextureSize != androidMax || android.format != TextureImporterFormat.ASTC_6x6)
        {
            android.overridden = true;
            android.maxTextureSize = androidMax;
            android.format = TextureImporterFormat.ASTC_6x6;
            ti.SetPlatformTextureSettings(android);
            dirty = true;
        }
        if (dirty) ti.SaveAndReimport();
    }

    private static Color32 EncodeNormal(Vector3 n) =>
        new Color32((byte)Mathf.Clamp(Mathf.RoundToInt((n.x * 0.5f + 0.5f) * 255f), 0, 255),
                    (byte)Mathf.Clamp(Mathf.RoundToInt((n.y * 0.5f + 0.5f) * 255f), 0, 255),
                    (byte)Mathf.Clamp(Mathf.RoundToInt((n.z * 0.5f + 0.5f) * 255f), 0, 255), 255);

    private static byte B(float v) => (byte)Mathf.Clamp(Mathf.RoundToInt(v * 255f), 0, 255);

    private static float Sample(float[] h, int w, int hgt, int x, int y, bool wrap)
    {
        if (wrap) { x = ((x % w) + w) % w; y = ((y % hgt) + hgt) % hgt; }
        else { x = Mathf.Clamp(x, 0, w - 1); y = Mathf.Clamp(y, 0, hgt - 1); }
        return h[y * w + x];
    }

    private static float Bilinear(float[] a, int w, int h, float x, float y)
    {
        if (x < 0f || y < 0f || x > w - 1 || y > h - 1) return 0f;
        int x0 = (int)x, y0 = (int)y, x1 = Mathf.Min(x0 + 1, w - 1), y1 = Mathf.Min(y0 + 1, h - 1);
        float fx = x - x0, fy = y - y0;
        return Mathf.Lerp(Mathf.Lerp(a[y0 * w + x0], a[y0 * w + x1], fx), Mathf.Lerp(a[y1 * w + x0], a[y1 * w + x1], fx), fy);
    }

    private static float[] MirrorU(float[] h, int w, int hgt)
    {
        var m = new float[h.Length];
        for (int y = 0; y < hgt; y++)
            for (int x = 0; x < w; x++) m[y * w + x] = h[y * w + (w - 1 - x)];
        return m;
    }

    /// <summary>Separable box blur (radius r, passes), wrapping or clamping.</summary>
    private static float[] Blur(float[] src, int w, int h, int r, int passes, bool wrap)
    {
        float[] a = (float[])src.Clone(), b = new float[src.Length];
        for (int p = 0; p < passes; p++)
        {
            for (int y = 0; y < h; y++)
                for (int x = 0; x < w; x++)
                {
                    float s = 0f;
                    for (int k = -r; k <= r; k++) s += Sample(a, w, h, x + k, y, wrap);
                    b[y * w + x] = s / (2 * r + 1);
                }
            for (int y = 0; y < h; y++)
                for (int x = 0; x < w; x++)
                {
                    float s = 0f;
                    for (int k = -r; k <= r; k++) s += Sample(b, w, h, x, y + k, wrap);
                    a[y * w + x] = s / (2 * r + 1);
                }
        }
        return a;
    }

    // Deterministic hash noise (no System.Random state across textures).
    private static float Hash(int x, int y, int seed)
    {
        unchecked
        {
            uint h = (uint)(x * 374761393 + y * 668265263 + seed * 2147483647);
            h = (h ^ (h >> 13)) * 1274126177u;
            h ^= h >> 16;
            return (h & 0xFFFFFF) / 16777215f;
        }
    }

    /// <summary>Tileable value noise with period p cells over a tile of size w.</summary>
    private static float ValueNoise(float x, float y, int period, int seed)
    {
        int x0 = Mathf.FloorToInt(x), y0 = Mathf.FloorToInt(y);
        float fx = x - x0, fy = y - y0;
        fx = fx * fx * (3f - 2f * fx); fy = fy * fy * (3f - 2f * fy);
        int Wp(int v) => ((v % period) + period) % period;
        float a = Hash(Wp(x0), Wp(y0), seed), b = Hash(Wp(x0 + 1), Wp(y0), seed);
        float c = Hash(Wp(x0), Wp(y0 + 1), seed), d = Hash(Wp(x0 + 1), Wp(y0 + 1), seed);
        return Mathf.Lerp(Mathf.Lerp(a, b, fx), Mathf.Lerp(c, d, fx), fy);
    }

    // ------------------------------------------------------------------------------------------------ paint flakes

    private static void FlakeMaps(int size, int cells, out Gen normal, out Gen mr)
    {
        normal = new Gen { W = size, H = size, Px = new Color32[size * size], Kind = Kind.Normal, AndroidMax = 512, Aniso = 8 };
        mr = new Gen { W = size, H = size, Px = new Color32[size * size], Kind = Kind.Data, AndroidMax = 512, Aniso = 8 };
        float cell = (float)size / cells;
        // One flake per cell (85 % of cells): centre, radius, facet normal, roughness.
        var cx = new float[cells * cells]; var cy = new float[cells * cells]; var rad = new float[cells * cells];
        var fn = new Vector3[cells * cells]; var fr = new float[cells * cells]; var on = new bool[cells * cells];
        for (int j = 0; j < cells; j++)
            for (int i = 0; i < cells; i++)
            {
                int k = j * cells + i;
                on[k] = Hash(i, j, 11) < 0.85f;
                cx[k] = (i + 0.15f + 0.7f * Hash(i, j, 12)) * cell;
                cy[k] = (j + 0.15f + 0.7f * Hash(i, j, 13)) * cell;
                rad[k] = cell * (0.32f + 0.22f * Hash(i, j, 14));
                // tilt: mostly gentle, a few steeper facets that catch the light from other angles
                float t = Hash(i, j, 15);
                float tilt = Mathf.Deg2Rad * (t < 0.85f ? 2f + 8f * t : 9f + 12f * (t - 0.85f) / 0.15f);
                float az = Hash(i, j, 16) * Mathf.PI * 2f;
                fn[k] = new Vector3(Mathf.Sin(tilt) * Mathf.Cos(az), Mathf.Sin(tilt) * Mathf.Sin(az), Mathf.Cos(tilt));
                fr[k] = 0.14f + 0.12f * Hash(i, j, 17);
            }
        for (int y = 0; y < size; y++)
        {
            for (int x = 0; x < size; x++)
            {
                int ci = Mathf.FloorToInt(x / cell), cj = Mathf.FloorToInt(y / cell);
                int best = -1; float bestD = float.MaxValue;
                for (int dj = -1; dj <= 1; dj++)
                    for (int di = -1; di <= 1; di++)
                    {
                        int ii = ((ci + di) % cells + cells) % cells, jj = ((cj + dj) % cells + cells) % cells;
                        int k = jj * cells + ii;
                        if (!on[k]) continue;
                        // wrapped distance
                        float dx = x + 0.5f - (cx[k] + (ci + di - ii) * cell), dy = y + 0.5f - (cy[k] + (cj + dj - jj) * cell);
                        float d = (dx * dx + dy * dy) / (rad[k] * rad[k]);
                        if (d < 1f && d < bestD) { bestD = d; best = k; }
                    }
                int p = y * size + x;
                if (best >= 0)
                {
                    normal.Px[p] = EncodeNormal(fn[best]);
                    mr.Px[p] = new Color32(255, B(fr[best]), B(0.8f), 255);
                }
                else
                {
                    normal.Px[p] = EncodeNormal(Vector3.forward);
                    mr.Px[p] = new Color32(255, B(0.36f), B(0.55f), 255);
                }
            }
        }
    }

    // ------------------------------------------------------------------------------------------------ tyre sidewall

    // The sidewall UVs are a planar disc: centre (0.5, 0.5), uv radius 0.5 = tyre radius 0.3607 m, rim edge 0.377.
    private static float[] SidewallHeight(int size, out float[] raised)
    {
        var h = new float[size * size];
        // Ridges: rim protector, two fine bead lines, the shoulder line.
        float Ring(float rho, float r0, float width, float amp)
        {
            float d = (rho - r0) / width;
            return d * d < 1f ? amp * (1f - d * d) * (1f - d * d) : 0f;
        }
        TextStrip brand = TextStrip.Render("AURELLE SPORT", 96, FontStyle.Bold, 10);
        TextStrip size1 = TextStrip.Render("255/35 R20 97Y", 96, FontStyle.Bold, 8);
        TextStrip small = TextStrip.Render("TUBELESS  RADIAL", 64, FontStyle.Bold, 6);
        TextStrip small2 = TextStrip.Render("ZR  ROTATION >", 64, FontStyle.Bold, 6);
        var text = new float[size * size];
        for (int y = 0; y < size; y++)
        {
            for (int x = 0; x < size; x++)
            {
                float u = (x + 0.5f) / size - 0.5f, v = (y + 0.5f) / size - 0.5f;
                float rho = Mathf.Sqrt(u * u + v * v);
                float phi = Mathf.Atan2(v, u); // image: clockwise as phi grows (rows go down)
                float hv = Ring(rho, 0.3815f, 0.0035f, 0.55f) + Ring(rho, 0.3905f, 0.0012f, 0.35f) + Ring(rho, 0.4705f, 0.0012f, 0.35f) +
                           Ring(rho, 0.4800f, 0.0030f, 0.45f);
                // fine circumferential texture on the flank (moulded micro ridges)
                if (rho > 0.395f && rho < 0.468f) hv += 0.04f * Mathf.Sin(rho * 2400f);
                h[y * size + x] = hv;
                float t = 0f;
                t = Mathf.Max(t, brand.ArcSample(rho, phi, -Mathf.PI / 2f, 0.4215f, 0.032f));
                t = Mathf.Max(t, size1.ArcSample(rho, phi, Mathf.PI / 2f, 0.4235f, 0.024f));
                t = Mathf.Max(t, small.ArcSample(rho, phi, 0f, 0.4265f, 0.013f));
                t = Mathf.Max(t, small2.ArcSample(rho, phi, Mathf.PI, 0.4265f, 0.013f));
                text[y * size + x] = t;
            }
        }
        float[] soft = Blur(text, size, size, 1, 2, false);
        raised = new float[h.Length];
        for (int i = 0; i < h.Length; i++)
        {
            h[i] += 0.9f * soft[i];
            raised[i] = Mathf.Clamp01(soft[i] + Mathf.Max(0f, h[i] - 0.9f * soft[i]) * 1.5f);
        }
        return h;
    }

    /// <summary>Sidewall metallic-roughness at half size: lettering and ridges smoother than the matte flank.</summary>
    private static Gen SidewallMr(float[] raised, int size, bool mirror)
    {
        int half = size / 2;
        var g = new Gen { W = half, H = half, Px = new Color32[half * half], Kind = Kind.Data, AndroidMax = 512, Aniso = 8 };
        for (int y = 0; y < half; y++)
            for (int x = 0; x < half; x++)
            {
                int sx = mirror ? size - 1 - 2 * x : 2 * x;
                float a = Mathf.Max(raised[2 * y * size + sx], raised[(2 * y + 1) * size + Mathf.Min(size - 1, sx + (mirror ? -1 : 1))]);
                g.Px[y * half + x] = new Color32(255, B(Mathf.Lerp(0.86f, 0.5f, a)), 0, 255);
            }
        return g;
    }

    /// <summary>A line of text rasterised from Unity's built-in font into an alpha strip (row 0 = top).</summary>
    private sealed class TextStrip
    {
        public int W, H;
        public float[] A;
        public int CapHeight;   // ascent of capitals in strip pixels
        public int Baseline;    // row of the baseline (from the top)

        public static TextStrip Render(string text, int size, FontStyle style, int tracking)
        {
            Font font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
            var strip = new TextStrip { W = 1, H = 1, A = new float[1] };
            if (font == null) { Debug.LogWarning("CarsRealism: built-in font missing, no lettering"); return strip; }
            font.RequestCharactersInTexture(text + "H", size, style);
            var fontTex = font.material.mainTexture;
            int fw = fontTex.width, fh = fontTex.height;
            RenderTexture rt = RenderTexture.GetTemporary(fw, fh, 0, RenderTextureFormat.ARGB32, RenderTextureReadWrite.Linear);
            RenderTexture prev = RenderTexture.active;
            Graphics.Blit(fontTex, rt);
            RenderTexture.active = rt;
            var read = new Texture2D(fw, fh, TextureFormat.RGBA32, false, true);
            read.ReadPixels(new Rect(0, 0, fw, fh), 0, 0);
            read.Apply();
            RenderTexture.active = prev;
            RenderTexture.ReleaseTemporary(rt);
            Color32[] px = read.GetPixels32();
            UnityEngine.Object.DestroyImmediate(read);
            // Alpha8 atlases blit to (0,0,0,a) or (a,a,a,1) depending on the platform: use whichever channel varies.
            int minA = 255, maxA = 0;
            foreach (Color32 c in px) { minA = Mathf.Min(minA, c.a); maxA = Mathf.Max(maxA, c.a); }
            bool useAlpha = maxA - minA > 32;
            var atlas = new float[fw * fh];
            for (int i = 0; i < px.Length; i++) atlas[i] = (useAlpha ? px[i].a : Mathf.Max(px[i].r, px[i].g)) / 255f;

            font.GetCharacterInfo('H', out CharacterInfo hInfo, size, style);
            int pen = 0, top = int.MinValue, bottom = int.MaxValue;
            var glyphs = new List<KeyValuePair<CharacterInfo, int>>();
            foreach (char c in text)
            {
                if (!font.GetCharacterInfo(c, out CharacterInfo ci, size, style)) continue;
                glyphs.Add(new KeyValuePair<CharacterInfo, int>(ci, pen));
                pen += ci.advance + tracking;
                if (ci.maxY > ci.minY) { top = Mathf.Max(top, ci.maxY); bottom = Mathf.Min(bottom, ci.minY); }
            }
            if (top == int.MinValue) return strip;
            const int pad = 4;
            strip.W = pen + 2 * pad;
            strip.H = top - bottom + 2 * pad;
            strip.A = new float[strip.W * strip.H];
            strip.Baseline = strip.H - 1 - (pad - bottom);
            strip.CapHeight = Mathf.Max(1, hInfo.maxY);
            foreach (var g in glyphs)
            {
                CharacterInfo ci = g.Key;
                int gw = ci.maxX - ci.minX, gh = ci.maxY - ci.minY;
                if (gw <= 0 || gh <= 0) continue;
                for (int gy = 0; gy < gh; gy++)
                    for (int gx = 0; gx < gw; gx++)
                    {
                        float tx = (gx + 0.5f) / gw, ty = (gy + 0.5f) / gh;
                        Vector2 uv = Vector2.Lerp(Vector2.Lerp(ci.uvBottomLeft, ci.uvBottomRight, tx), Vector2.Lerp(ci.uvTopLeft, ci.uvTopRight, tx), ty);
                        float a = Bilinear(atlas, fw, fh, uv.x * fw - 0.5f, uv.y * fh - 0.5f);
                        int sx = pad + g.Value + ci.minX + gx;
                        int fromBottom = pad + (ci.minY - bottom) + gy;
                        int row = strip.H - 1 - fromBottom;
                        if (sx < 0 || sx >= strip.W || row < 0 || row >= strip.H) continue;
                        int k = row * strip.W + sx;
                        strip.A[k] = Mathf.Max(strip.A[k], a);
                    }
            }
            return strip;
        }

        /// <summary>
        /// Coverage at disc polar coordinates (rho, phi) for this text centred on angle phiC, baseline at radius
        /// baseRho, capitals capRho tall, letters upright (pointing away from the centre), reading clockwise.
        /// </summary>
        public float ArcSample(float rho, float phi, float phiC, float baseRho, float capRho)
        {
            if (A.Length <= 1) return 0f;
            float scale = capRho / CapHeight;               // uv units per strip pixel
            float dPhi = Mathf.DeltaAngle(phiC * Mathf.Rad2Deg, phi * Mathf.Rad2Deg) * Mathf.Deg2Rad;
            float s = dPhi * baseRho;                       // arc length from the centre of the text
            float sx = W * 0.5f + s / scale;
            float sy = Baseline - (rho - baseRho) / scale;  // outward = up = smaller row
            return Bilinear(A, W, H, sx, sy);
        }
    }

    // ------------------------------------------------------------------------------------------------ brake disc

    // Disc UVs: u = angle (0..1 around), v = radius from the inner edge (0.092 m) to the outer edge (0.2007 m).
    private static void DiscMaps(int w, int h, out Gen baseMap, out Gen normal, out Gen mr)
    {
        baseMap = new Gen { W = w, H = h, Px = new Color32[w * h], Kind = Kind.Color, AndroidMax = 1024, Aniso = 8 };
        mr = new Gen { W = w, H = h, Px = new Color32[w * h], Kind = Kind.Data, AndroidMax = 1024, Aniso = 8 };
        const float rIn = 0.0922f, rOut = 0.2007f, ringIn = 0.123f, holeR = 0.0042f, chamfer = 0.0011f;
        var height = new float[w * h];
        // Cross-drilled holes: 3 rows, 18 groups, each row a little further round (spiral).
        var holes = new List<Vector2>();
        float[] rows = { 0.138f, 0.158f, 0.178f };
        for (int gIdx = 0; gIdx < 18; gIdx++)
            for (int r = 0; r < rows.Length; r++)
            {
                float a = (gIdx + 0.28f * r) / 18f * Mathf.PI * 2f;
                holes.Add(new Vector2(Mathf.Cos(a), Mathf.Sin(a)) * rows[r]);
            }
        for (int y = 0; y < h; y++)
        {
            float rad = Mathf.Lerp(rIn, rOut, (y + 0.5f) / h);
            // turning marks: concentric, varying with radius only
            float turn = 0.5f * ValueNoise(rad * 9000f, 0.5f, 100000, 3) + 0.5f * ValueNoise(rad * 2600f, 2.5f, 100000, 4);
            for (int x = 0; x < w; x++)
            {
                float ang = (x + 0.5f) / w * Mathf.PI * 2f;
                var p = new Vector2(Mathf.Cos(ang), Mathf.Sin(ang)) * rad;
                float hv, metal = 1f, rough;
                Color col;
                if (rad < ringIn)
                {
                    // hat: machined, darker, a stepped shoulder
                    hv = rad < 0.112f ? 0.0f : 0.35f;
                    col = new Color(0.36f, 0.36f, 0.37f);
                    rough = 0.42f;
                }
                else
                {
                    hv = 0.25f + 0.2f * turn;
                    float shade = 0.56f + 0.08f * turn;
                    col = new Color(shade, shade, shade * 1.01f);
                    rough = 0.30f + 0.12f * turn;
                    // outer edge chamfer
                    if (rad > rOut - 0.0015f) { hv -= (rad - (rOut - 0.0015f)) / 0.0015f * 0.3f; rough = 0.25f; }
                }
                float dMin = float.MaxValue;
                foreach (Vector2 c in holes) dMin = Mathf.Min(dMin, (p - c).sqrMagnitude);
                dMin = Mathf.Sqrt(dMin);
                if (dMin < holeR)
                {
                    hv = -0.6f; col = new Color(0.015f, 0.015f, 0.016f); rough = 0.9f; metal = 0.2f;
                }
                else if (dMin < holeR + chamfer)
                {
                    float t = (dMin - holeR) / chamfer;
                    hv = Mathf.Lerp(-0.25f, hv, t);
                    col = new Color(0.72f, 0.72f, 0.73f); rough = 0.18f;
                }
                int k = y * w + x;
                height[k] = hv;
                baseMap.Px[k] = new Color32(B(Mathf.LinearToGammaSpace(col.r)), B(Mathf.LinearToGammaSpace(col.g)), B(Mathf.LinearToGammaSpace(col.b)), 255);
                mr.Px[k] = new Color32(255, B(rough), B(metal), 255);
            }
        }
        // Pixels are anisotropic (u spans 2 pi r, v spans 0.11 m): scale the strength per axis via the height values.
        normal = Gen.NormalFromHeight(height, w, h, 3.5f, true, Kind.Normal, 1024, 8);
    }

    // ------------------------------------------------------------------------------------------------ interior

    /// <summary>Pebbled leather: cellular height (cells raised, creases between) plus a little noise.</summary>
    private static float[] LeatherGrain(int size, int cells, int seed)
    {
        var h = new float[size * size];
        float cell = (float)size / cells;
        for (int y = 0; y < size; y++)
            for (int x = 0; x < size; x++)
            {
                float gx = x / cell, gy = y / cell;
                int ix = Mathf.FloorToInt(gx), iy = Mathf.FloorToInt(gy);
                float f1 = 9f, f2 = 9f;
                for (int dj = -1; dj <= 1; dj++)
                    for (int di = -1; di <= 1; di++)
                    {
                        int cxI = ix + di, cyI = iy + dj;
                        int wx = ((cxI % cells) + cells) % cells, wy = ((cyI % cells) + cells) % cells;
                        float px = cxI + Hash(wx, wy, seed), py = cyI + Hash(wx, wy, seed + 1);
                        float d = Mathf.Sqrt((gx - px) * (gx - px) + (gy - py) * (gy - py));
                        if (d < f1) { f2 = f1; f1 = d; } else if (d < f2) f2 = d;
                    }
                float crease = Mathf.Clamp01((f2 - f1) * 3.2f);
                float n = ValueNoise(x / 8f, y / 8f, size / 8, seed + 7);
                h[y * size + x] = Mathf.Sqrt(crease) * 0.9f + 0.15f * n;
            }
        return Blur(h, size, size, 1, 1, true);
    }

    /// <summary>Perforated insert: the leather grain with a 8 x 8 hole grid per tile (offset every other row).</summary>
    private static Gen LeatherPerforated(int size, float[] grain)
    {
        var baseMap = new Gen { W = size, H = size, Px = new Color32[size * size], Kind = Kind.Color, AndroidMax = 512, Aniso = 4 };
        var h = (float[])grain.Clone();
        const int n = 8;
        float pitch = (float)size / n, hole = pitch * 0.17f;
        for (int y = 0; y < size; y++)
            for (int x = 0; x < size; x++)
            {
                int row = Mathf.FloorToInt(y / pitch);
                float ox = (row % 2 == 0) ? 0f : pitch * 0.5f;
                float lx = ((x + 0.5f - ox) % pitch + pitch) % pitch - pitch * 0.5f;
                float ly = ((y + 0.5f) % pitch) - pitch * 0.5f;
                float d = Mathf.Sqrt(lx * lx + ly * ly);
                float shade = 0.9f + 0.1f * grain[y * size + x];
                int k = y * size + x;
                if (d < hole) { h[k] = -0.8f; shade = 0.08f; }
                else if (d < hole * 1.6f) { float t = (d - hole) / (hole * 0.6f); h[k] = Mathf.Lerp(-0.3f, h[k], t); shade *= Mathf.Lerp(0.6f, 1f, t); }
                byte s = B(Mathf.LinearToGammaSpace(shade));
                baseMap.Px[k] = new Color32(s, s, s, 255);
            }
        return baseMap;
    }

    private static float[] Suede(int size, int seed)
    {
        var h = new float[size * size];
        for (int y = 0; y < size; y++)
            for (int x = 0; x < size; x++)
                h[y * size + x] = 0.6f * Hash(x, y, seed) + 0.4f * ValueNoise(x / 3f, y / 6f, size / 3 > 0 ? size / 3 : 1, seed + 1);
        return Blur(h, size, size, 1, 1, true);
    }

    /// <summary>2x2 twill: tows per tile along each axis; base brightness differs by tow direction.</summary>
    private static void CarbonTwill(int size, int tows, out Gen baseMap, out Gen normal)
    {
        baseMap = new Gen { W = size, H = size, Px = new Color32[size * size], Kind = Kind.Color, AndroidMax = 512, Aniso = 8 };
        var h = new float[size * size];
        float t = (float)size / tows;
        for (int y = 0; y < size; y++)
            for (int x = 0; x < size; x++)
            {
                int i = Mathf.FloorToInt(x / t), j = Mathf.FloorToInt(y / t);
                bool warpUp = ((i + j) % 4 + 4) % 4 < 2;
                float lx = (x + 0.5f) / t - i, ly = (y + 0.5f) / t - j; // 0..1 inside the cell
                // rounded tow cross-section across its width, fibre striation along it
                float across = warpUp ? lx : ly, along = warpUp ? y : x;
                float bulge = Mathf.Sin(across * Mathf.PI);
                float fibre = 0.08f * Mathf.Sin(along * 2.1f + Hash(warpUp ? i : j, 3, 5) * 6f) * Hash(x, y, 9);
                h[y * size + x] = 0.7f * Mathf.Pow(bulge, 0.6f) + fibre;
                float shade = warpUp ? 0.050f : 0.030f;
                shade *= 0.85f + 0.3f * bulge;
                byte s = B(Mathf.LinearToGammaSpace(shade));
                baseMap.Px[y * size + x] = new Color32(s, s, B(Mathf.LinearToGammaSpace(shade * 1.04f)), 255);
            }
        normal = Gen.NormalFromHeight(h, size, size, 2.6f, true, Kind.Normal, 512, 8);
    }

    private static float[] Brushed(int size, int seed)
    {
        var h = new float[size * size];
        for (int y = 0; y < size; y++)
        {
            for (int x = 0; x < size; x++)
            {
                // fine lines along x: noise varies fast across y, slowly along x
                float v = 0.55f * ValueNoise(x / 96f, y * 1.0f, size, seed) + 0.3f * ValueNoise(x / 40f, y / 2f, size / 2, seed + 1) +
                          0.15f * ValueNoise(x / 200f, y / 7f, size / 7 > 0 ? size / 7 : 1, seed + 2);
                h[y * size + x] = v;
            }
        }
        return h;
    }

    // ------------------------------------------------------------------------------------------------ plate

    /// <summary>Black plate with a thin white border and raised white AURELLE lettering (plate UVs cover 0..1).</summary>
    private static Gen LicensePlate(int w, int h)
    {
        var g = new Gen { W = w, H = h, Px = new Color32[w * h], Kind = Kind.Color, AndroidMax = 512, Aniso = 4 };
        var img = new float[w * h];
        void Text(string s, int px, float cx, float baseRow, int tracking)
        {
            TextStrip t = TextStrip.Render(s, px, FontStyle.Bold, tracking);
            int x0 = Mathf.RoundToInt(cx - t.W * 0.5f), y0 = Mathf.RoundToInt(baseRow - t.Baseline);
            for (int y = 0; y < t.H; y++)
                for (int x = 0; x < t.W; x++)
                {
                    int xx = x0 + x, yy = y0 + y;
                    if (xx < 0 || yy < 0 || xx >= w || yy >= h) continue;
                    img[yy * w + xx] = Mathf.Max(img[yy * w + xx], t.A[y * t.W + x]);
                }
        }
        Text("AURELLE", 150, w * 0.5f, h * 0.68f, 18);
        Text("MOTOR HOUSE", 34, w * 0.5f, h * 0.9f, 10);
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
            {
                int edge = Mathf.Min(Mathf.Min(x, w - 1 - x), Mathf.Min(y, h - 1 - y));
                float border = edge >= 10 && edge < 15 ? 1f : 0f;
                float a = Mathf.Max(img[y * w + x], border);
                byte v = B(Mathf.LinearToGammaSpace(Mathf.Lerp(0.012f, 0.82f, a)));
                g.Px[y * w + x] = new Color32(v, v, v, 255);
            }
        return g;
    }

    // ------------------------------------------------------------------------------------------------ display

    private static Gen Display(int w, int h)
    {
        var g = new Gen { W = w, H = h, Px = new Color32[w * h], Kind = Kind.Color, AndroidMax = 512, Aniso = 4 };
        var ice = new Color(0.70f, 0.86f, 1.0f);
        var dim = new Color(0.10f, 0.16f, 0.22f);
        var red = new Color(0.95f, 0.10f, 0.08f);
        var img = new Color[w * h];
        for (int i = 0; i < img.Length; i++) img[i] = new Color(0.004f, 0.006f, 0.01f);
        void Put(int x, int y, Color c, float a)
        {
            if (x < 0 || y < 0 || x >= w || y >= h || a <= 0f) return;
            img[y * w + x] = Color.Lerp(img[y * w + x], c, Mathf.Clamp01(a));
        }
        void Text(string s, int px, float cx, float baseRow, Color c)
        {
            TextStrip t = TextStrip.Render(s, px, FontStyle.Bold, 2);
            int x0 = Mathf.RoundToInt(cx - t.W * 0.5f), y0 = Mathf.RoundToInt(baseRow - t.Baseline);
            for (int y = 0; y < t.H; y++) for (int x = 0; x < t.W; x++) Put(x0 + x, y0 + y, c, t.A[y * t.W + x]);
        }
        // Rev arc (bar graph) on the left, power arc on the right, around a central speed readout.
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
            {
                foreach (int side in new[] { -1, 1 })
                {
                    float cxA = w * 0.5f + side * 300f, cyA = h * 0.62f;
                    float dx = x - cxA, dy = y - cyA, r = Mathf.Sqrt(dx * dx + dy * dy);
                    if (r < 78f || r > 92f) continue;
                    float a = Mathf.Atan2(-dy, dx * side) * Mathf.Rad2Deg; // 0 = outward, 90 = up
                    if (a < -40f || a > 200f) continue;
                    float seg = Mathf.Repeat(a + 40f, 12f);
                    if (seg > 9f) continue;
                    float lit = side < 0 ? (a > 120f ? 1f : 0f) : (a > 160f ? 1f : 0f);
                    Put(x, y, lit > 0f ? (side < 0 && a < 20f ? red : ice) : dim, 1f);
                }
                // thin frame line near the top and bottom
                if ((y == 18 || y == h - 19) && x > 120 && x < w - 120) Put(x, y, dim, 1f);
            }
        Text("0", 120, w * 0.5f, h * 0.66f, ice);
        Text("km/h", 30, w * 0.5f, h * 0.82f, dim * 3f);
        Text("AURELLE", 28, w * 0.5f, h * 0.22f, ice);
        Text("P", 44, w * 0.5f - 300f, h * 0.70f, ice);
        Text("READY", 22, w * 0.5f + 300f, h * 0.70f, new Color(0.35f, 0.9f, 0.55f));
        Text("RANGE 412 km", 20, w * 0.5f + 300f, h * 0.84f, dim * 3f);
        Text("21.0 C", 20, w * 0.5f - 300f, h * 0.84f, dim * 3f);
        for (int i = 0; i < img.Length; i++)
            g.Px[i] = new Color32(B(Mathf.LinearToGammaSpace(img[i].r)), B(Mathf.LinearToGammaSpace(img[i].g)), B(Mathf.LinearToGammaSpace(img[i].b)), 255);
        return g;
    }
}
#endif
